"""
urobot_driver node for the surgical arm ROS2 project, made for the OR cleaning robot project in the HERO Lab
written by Connor McKelvey | connormckelvey@utexas.edu
This node is responsible for interfacing with the URobot Lite6 robotic arm. listens to either cartesian pose commands in meters or joint angle commands in degrees and sends them to the robot.
you can't send both joint angles and coordinates because the driver must be launched in either cartesian or joint mode.
publishes the current cartesian pose in meters and joint angles in degrees.

Inputs: Target cartesian pose in meters (geometry_msgs/Pose), Target joint angles in degrees (std_msgs/Float32MultiArray)
Outputs: Current cartesian pose in meters (geometry_msgs/Pose), Current joint angles in degrees (std_msgs/Float32MultiArray)
Services: OpenGripper, CloseGripper, EnableRobot, StopRobot, GoHome

to call the services use the following commands:
ros2 service call /arm/OpenGripper std_srvs/srv/Trigger
ros2 service call /arm/CloseGripper std_srvs/srv/Trigger
ros2 service call /arm/EnableRobot std_srvs/srv/Trigger
ros2 service call /arm/StopRobot std_srvs/srv/Trigger
ros2 service call /arm/GoHome std_srvs/srv/Trigger

modes:
cartesian - planned cartesian movement using set_position
cartesian_realtime - realtime cartesian movement using set_servo_cartesian
joint - joint movement using set_servo_angle
"""

import time

import rclpy
from geometry_msgs.msg import Pose
from rclpy.node import Node
from scipy.spatial.transform import Rotation as R
from std_msgs.msg import Float32MultiArray
from std_srvs.srv import Trigger
from xarm.wrapper import XArmAPI


class URobotDriverNode(Node):
    def __init__(self):
        super().__init__('urobot_driver')

        #params
        self.declare_parameter('ip','192.168.1.184')
        self.declare_parameter('feedback_period',0.05)
        self.declare_parameter('mode','cartesian')
        self.declare_parameter('wait',False)
        self.declare_parameter('speed',100.0)
        self.declare_parameter('acceleration',1000.0)

        self.ip = self.get_parameter('ip').value
        self.feedback_period = self.get_parameter('feedback_period').value
        self.mode = self.get_parameter('mode').value
        self.wait = self.get_parameter('wait').value
        self.speed = self.get_parameter('speed').value
        self.acceleration = self.get_parameter('acceleration').value

        self.cartesian_control = self.mode in ['cartesian','cartesian_realtime']
        self.cartesian_realtime = self.mode == 'cartesian_realtime'
        self.joint_control = self.mode == 'joint'
        self.robot_enabled = False

        self.robot = XArmAPI(self.ip,is_radian=False)

        self.robot.motion_enable(enable=True)
        self.robot.set_mode(0)
        self.robot.set_state(state=0)
        time.sleep(0.1)

        self.move_home()
        self.set_robot_mode()

        self.robot_enabled = True
        self.get_logger().info(f"URobot CONNECTED | mode={self.mode}")

        # ROS2 Subscribers and Publishers and Services values are in degrees and m
        self.cartesian_subscription = self.create_subscription(Pose,'/arm/target_cartesian_pose',self.target_cartesian_pose_callback,1)
        self.joint_subscription = self.create_subscription(Float32MultiArray,'/arm/target_joint_angles',self.target_joint_angle_callback,10)

        self.current_pose_pub = self.create_publisher(Pose,'/arm/current_cartesian_pose',10)
        self.current_state_pub = self.create_publisher(Float32MultiArray,'/arm/current_joint_angles',10)

        self.close_gripper_srv = self.create_service(Trigger,'arm/CloseGripper',self.close_gripper_callback)
        self.open_gripper_srv = self.create_service(Trigger,'arm/OpenGripper',self.open_gripper_callback)
        self.enable_robot_srv = self.create_service(Trigger,'arm/EnableRobot',self.enable_robot_callback)
        self.stop_robot_srv = self.create_service(Trigger,'arm/StopRobot',self.stop_robot_callback)
        self.go_home_srv = self.create_service(Trigger,'arm/GoHome',self.go_home_callback)

        self.feedback_timer = self.create_timer(self.feedback_period,self.feedback_callback)

#subscription callbacks
    def target_cartesian_pose_callback(self,msg):
        if not self.cartesian_control or not self.robot_enabled:
            return

        target = self.pose_msg_to_list(msg)

        if self.cartesian_realtime:
            code = self.robot.set_servo_cartesian(target,is_radian=False)
        else:
            code = self.robot.set_position(
                x=target[0],
                y=target[1],
                z=target[2],
                roll=target[3],
                pitch=target[4],
                yaw=target[5],
                speed=self.speed,
                mvacc=self.acceleration,
                is_radian=False,
                wait=self.wait
            )

        if code != 0:
            self.get_logger().error(f'Cartesian command failed with code: {code}')

    def target_joint_angle_callback(self,msg):
        if not self.joint_control or not self.robot_enabled:
            return

        if len(msg.data) != 6:
            self.get_logger().warning(f'Joint command must contain 6 angles, received {len(msg.data)}')
            return

        joint_angles = [float(angle) for angle in msg.data]

        code = self.robot.set_servo_angle(
            angle=joint_angles,
            speed=self.speed,
            mvacc=self.acceleration,
            is_radian=False,
            wait=self.wait
        )

        if code != 0:
            self.get_logger().error(f'Joint position command failed with code: {code}')

#timer callbacks
    def feedback_callback(self):
        current_pose_msg = Pose()
        current_joint_msg = Float32MultiArray()

        code,current_pose = self.robot.get_position(is_radian=False)

        if code != 0 or current_pose is None:
            return

        current_pose_msg.position.x = float(current_pose[0])/1000.0
        current_pose_msg.position.y = float(current_pose[1])/1000.0
        current_pose_msg.position.z = float(current_pose[2])/1000.0

        quat = R.from_euler('xyz',[current_pose[3],current_pose[4],current_pose[5]],degrees=True).as_quat()

        current_pose_msg.orientation.x = float(quat[0])
        current_pose_msg.orientation.y = float(quat[1])
        current_pose_msg.orientation.z = float(quat[2])
        current_pose_msg.orientation.w = float(quat[3])

        code,joint_angles = self.robot.get_servo_angle(is_radian=False)

        if code != 0 or joint_angles is None:
            return

        current_joint_msg.data = [float(angle) for angle in joint_angles]

        self.current_pose_pub.publish(current_pose_msg)
        self.current_state_pub.publish(current_joint_msg)

#service callbacks
    def close_gripper_callback(self,request,response):
        code = self.robot.close_lite6_gripper()

        response.success = code == 0
        response.message = "Gripper Closed" if response.success else f"Gripper failed to close, code: {code}"

        return response

    def open_gripper_callback(self,request,response):
        code = self.robot.open_lite6_gripper()

        response.success = code == 0
        response.message = "Gripper Opened" if response.success else f"Gripper failed to open, code: {code}"

        return response

    def enable_robot_callback(self,request,response):
        enable_code = self.robot.motion_enable(enable=True)
        mode_code,state_code = self.set_robot_mode()

        self.robot_enabled = enable_code == 0 and mode_code == 0 and state_code == 0

        response.success = self.robot_enabled
        response.message = "URobot enabled" if response.success else f"Could not enable URobot, enable code: {enable_code}, mode code: {mode_code}, state code: {state_code}"

        return response

    def stop_robot_callback(self,request,response):
        code = self.robot.set_state(4)
        self.robot_enabled = False

        response.success = code == 0
        response.message = "URobot stopped" if response.success else f"Could not stop URobot, code: {code}"

        return response

    def go_home_callback(self,request,response):
        self.robot_enabled = False

        mode_code = self.robot.set_mode(0)
        state_code = self.robot.set_state(state=0)
        time.sleep(0.1)

        home_code = self.move_home()
        mode_code,state_code = self.set_robot_mode()

        self.robot_enabled = home_code == 0 and mode_code == 0 and state_code == 0

        response.success = self.robot_enabled
        response.message = "URobot moved home" if response.success else f"Could not move URobot home, code: {home_code}"

        return response

#helper methods
    def pose_msg_to_list(self,msg):
        roll,pitch,yaw = R.from_quat([
            msg.orientation.x,
            msg.orientation.y,
            msg.orientation.z,
            msg.orientation.w
        ]).as_euler('xyz',degrees=True)

        return [
            msg.position.x * 1000.0,
            msg.position.y * 1000.0,
            msg.position.z * 1000.0,
            float(roll),
            float(pitch),
            float(yaw)
        ]

    def move_home(self):
        return self.robot.set_position(
            x=300,
            y=0,
            z=200,
            roll=180,
            pitch=0,
            yaw=0,
            speed=self.speed,
            mvacc=self.acceleration,
            is_radian=False,
            wait=True
        )

    def set_robot_mode(self):
        if self.cartesian_realtime:
            mode_code = self.robot.set_mode(1)
        else:
            mode_code = self.robot.set_mode(0)

        state_code = self.robot.set_state(state=0)
        time.sleep(0.1)

        return mode_code,state_code

    def destroy_node(self):
        self.get_logger().info("Disconnecting from robot...")

        self.robot.set_state(4)
        self.robot.disconnect()

        super().destroy_node()


def main(args=None):
    rclpy.init(args=args)
    node = URobotDriverNode()

    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()

        if rclpy.ok():
            rclpy.shutdown()


if __name__ == '__main__':
    main()